'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { AdminUser } from '@/lib/auth';

interface AdminSidebarProps {
  user: AdminUser;
}

const navigation = [
  { name: 'Dashboard', href: '/admin', icon: HomeIcon },
  { name: 'Blog Posts', href: '/admin/posts', icon: DocumentIcon },
  { name: 'Testimonios', href: '/admin/testimonials', icon: ChatIcon },
  { name: 'Casos de Éxito', href: '/admin/cases', icon: TrophyIcon },
  { name: 'Mensajes', href: '/admin/messages', icon: InboxIcon },
  { name: 'Analytics', href: '/admin/analytics', icon: ChartIcon },
  { name: 'Configuración', href: '/admin/settings', icon: CogIcon },
];

export default function AdminSidebar({ user }: AdminSidebarProps) {
  const pathname = usePathname();

  return (
    <>
      {/* Desktop sidebar */}
      <div className="hidden lg:fixed lg:inset-y-0 lg:z-50 lg:flex lg:w-72 lg:flex-col">
        <div className="flex grow flex-col gap-y-5 overflow-y-auto bg-primary-800/50 backdrop-blur-xl border-r border-white/5 px-6 pb-4">
          {/* Logo */}
          <div className="flex h-16 shrink-0 items-center">
            <Link href="/admin" className="flex items-center gap-2">
              <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-accent-500 to-accent-600 flex items-center justify-center">
                <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                </svg>
              </div>
              <span className="text-xl font-bold text-white">CreamosTech</span>
            </Link>
          </div>

          {/* Navigation */}
          <nav className="flex flex-1 flex-col">
            <ul role="list" className="flex flex-1 flex-col gap-y-7">
              <li>
                <ul role="list" className="-mx-2 space-y-1">
                  {navigation.map((item) => {
                    const isActive = pathname === item.href || (item.href !== '/admin' && pathname.startsWith(item.href));
                    return (
                      <li key={item.name}>
                        <Link
                          href={item.href}
                          className={`group flex gap-x-3 rounded-lg p-3 text-sm font-medium transition-all ${
                            isActive
                              ? 'bg-accent-500/20 text-accent-400'
                              : 'text-primary-300 hover:text-white hover:bg-white/5'
                          }`}
                        >
                          <item.icon className={`h-5 w-5 shrink-0 ${isActive ? 'text-accent-400' : 'text-primary-400 group-hover:text-white'}`} />
                          {item.name}
                          {item.name === 'Mensajes' && (
                            <span className="ml-auto inline-flex h-5 min-w-5 items-center justify-center rounded-full bg-accent-500 px-1.5 text-xs font-semibold text-white">
                              3
                            </span>
                          )}
                        </Link>
                      </li>
                    );
                  })}
                </ul>
              </li>

              {/* User profile at bottom */}
              <li className="mt-auto">
                <div className="flex items-center gap-x-4 p-3 rounded-lg bg-white/5">
                  <div className="h-10 w-10 rounded-full bg-gradient-to-br from-accent-400 to-accent-600 flex items-center justify-center">
                    <span className="text-sm font-semibold text-white">
                      {user.name.split(' ').map(n => n[0]).join('')}
                    </span>
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium text-white truncate">{user.name}</p>
                    <p className="text-xs text-primary-400 truncate">{user.role}</p>
                  </div>
                </div>
              </li>
            </ul>
          </nav>
        </div>
      </div>

      {/* Mobile sidebar toggle - will be controlled by AdminHeader */}
    </>
  );
}

